typedef struct { uint32_t op; } cmd_base;        /* tag carried on the wire */

static int cmd_render(const cmd_base *c) { return render(((const render_cmd *)c)->report_id); }
static int (*const dispatch[])(const cmd_base *) = { [OP_PING] = cmd_ping, [OP_RENDER] = cmd_render };

int invoker_run(const uint8_t *buf, size_t len) {
    cmd_base *c = decode(buf, len);            /* protobuf-c / msgpack-c / hand-written */
    if (!c || c->op >= sizeof dispatch / sizeof *dispatch) return -1;  /* allow-list the tag */
    return dispatch[c->op] ? dispatch[c->op](c) : -1;
}
